catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var urlParams = new URLSearchParams(top.window.location.search);
    var paraId = urlParams.get('catitem_id');
    if (paraId) {
        var ga = new GlideAjax('PrefillCatalogItemUtils');
        ga.addParam('sysparm_name', 'getPreviousRequestInfo');
        ga.addParam('sysparm_paraId', paraId);
        ga.getXMLAnswer(function(answer) {
            if (answer) {
                try {
                    var data = JSON.parse(answer);
                    if (data.question1) {
                        g_form.setValue('question1', data.question1);
                    }
                    if (data.question2) {
                        g_form.setValue('question2', data.question2);
                    }
                } catch (e) {}
            }
        });
        var sta = new GlideAjax('GetStateFromLastForm');
        sta.addParam('sysparm_name', 'getStateFun');
        sta.addParam('sysparm_sys_id', paraId);
        sta.getXMLAnswer(function(answer) {
            if (answer) {
                g_form.setValue('from', answer);
            }
        });
    }
}
